{
  "name": "@open-inspect/github-bot",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "esbuild src/index.ts --bundle --format=esm --outfile=dist/index.js --platform=browser --target=es2022 --external:cloudflare:* --external:node:*",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage",
    "typecheck": "tsc --noEmit",
    "lint": "eslint src/",
    "lint:fix": "eslint src/ --fix"
  },
  "dependencies": {
    "@cloudflare/workers-types": "^4.20241230.0",
    "@open-inspect/shared": "file:../shared",
    "hono": "^4.12.26",
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@vitest/coverage-v8": "^4.1.0",
    "esbuild": "^0.28.1",
    "typescript": "^5.7.2",
    "vitest": "^4.1.0"
  }
}

{
  "name": "@open-inspect/opencomputer-infra",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "esbuild src/build-template.ts --bundle --format=esm --platform=node --target=node22 --outfile=dist/build-template.js --packages=external",
    "build-template": "npm run build && npm run build-template:run --",
    "build-template:run": "node dist/build-template.js",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@opencomputer/sdk": "^0.9.1",
    "esbuild": "^0.28.1",
    "typescript": "^5.7.2"
  }
}

{
  "name": "@open-inspect/shared",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tsconfig.test.json",
    "test": "vitest run",
    "lint": "eslint src/",
    "lint:fix": "eslint src/ --fix"
  },
  "devDependencies": {
    "typescript": "^5.7.2",
    "vitest": "^4.1.0"
  },
  "dependencies": {
    "@octokit/webhooks-types": "^7.6.1",
    "cron-parser": "^5.5.0",
    "zod": "^4.4.3"
  }
}
